{"code": "import numpy as np
from scipy.optimize import minimize

def objective(x):
    a, b, c = x
    return -(abs(a) + abs(b) + abs(c))

def constraint1(x):
    a, b, c = x
    return 1 - (a * 0**2 + b * 0 + c)

def constraint2(x):
    a, b, c = x
    return 1 + (a * 0**2 + b * 0 + c)

def constraint3(x):
    a, b, c = x
    return 1 - (a * 1**2 + b * 1 + c)

def constraint4(x):
    a, b, c = x
    return 1 + (a * 1**2 + b * 1 + c)

def constraint5(x):
    a, b, c = x
    if a == 0:
        return 1
    x_v = -b / (2 * a)
    if 0 <= x_v <= 1:
        return 1 - (a * x_v**2 + b * x_v + c)
    return 1

def constraint6(x):
    a, b, c = x
    if a == 0:
        return 1
    x_v = -b / (2 * a)
    if 0 <= x_v <= 1:
        return 1 + (a * x_v**2 + b * x_v + c)
    return 1

cons = [
    {'type': 'ineq', 'fun': constraint1},
    {'type': 'ineq', 'fun': constraint2},
    {'type': 'ineq', 'fun': constraint3},
    {'type': 'ineq', 'fun': constraint4},
    {'type': 'ineq', 'fun': constraint5},
    {'type': 'ineq', 'fun': constraint6}
]

best_val = -np.inf
best_x = None
for _ in range(100):
    x0 = np.random.uniform(-10, 10, 3)
    res = minimize(objective, x0, constraints=cons, method='SLSQP')
    if not res.success:
        continue
    val = -res.fun
    if val > best_val:
        best_val = val
        best_x = res.x

print(f"Best value: {best_val}")
print(f"Best a, b, c: {best_x}")"}
